// The synthetic scene's broadcast voice: "This is SDR Flex. You are listening to a synthetic
// FM broadcast." 4.88 s at 16 kHz.
//
// Provenance: spoken by Piper 1.8.0 with the en_US-ljspeech-high voice, whose training
// data, the LJ Speech dataset, is public domain. Resampled from 22.05 kHz with scipy's
// resample_poly(320, 441), normalized to a 0.98 peak, then companded with μ = 255 and
// quantized to a byte: c = sign(x) ln(1 + μ|x|) / ln(1 + μ), stored as round((c + 1) · 127.5).
// Nobody transmitted it. Inline, so the scene stays a synchronous function of time in a
// page with no build step and in Node alike.

const B64 =
  '';

export const VOICE_RATE = 16_000;

// Decoded by hand rather than with atob or Buffer: the same code in a page and in Node, and
// measured, Buffer's path left the scene's generator about 40% slower for the rest of the
// process.
function bytes(b64) {
  const map = new Uint8Array(128);
  const abc = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  for (let i = 0; i < 64; i++) map[abc.charCodeAt(i)] = i;
  const pad = b64.endsWith('==') ? 2 : b64.endsWith('=') ? 1 : 0;
  const out = new Uint8Array((b64.length / 4) * 3 - pad);
  for (let i = 0, o = 0; i < b64.length; i += 4) {
    const v = (map[b64.charCodeAt(i)] << 18) | (map[b64.charCodeAt(i + 1)] << 12) |
              (map[b64.charCodeAt(i + 2)] << 6) | map[b64.charCodeAt(i + 3)];
    if (o < out.length) out[o++] = v >> 16;
    if (o < out.length) out[o++] = (v >> 8) & 255;
    if (o < out.length) out[o++] = v & 255;
  }
  return out;
}

/** The clip as floats, -1..1. */
export function voice() {
  const q = bytes(B64), mu = 255, out = new Float32Array(q.length);
  for (let i = 0; i < q.length; i++) {
    const c = q[i] / 127.5 - 1;
    out[i] = Math.sign(c) * (Math.pow(1 + mu, Math.abs(c)) - 1) / mu;
  }
  return out;
}
